import java.net.http.HttpClient
import java.net.http.HttpRequest
import java.net.http.HttpResponse
import java.net.URI
import java.nio.charset.StandardCharsets
import groovy.json.JsonSlurper
import groovy.json.JsonBuilder

try {
    // Get OAuth configuration
    def clientId = System.getenv("GITHUB_CLIENT_ID") ?: "your_github_client_id"
    def clientSecret = System.getenv("GITHUB_CLIENT_SECRET") ?: "your_github_client_secret"
    def tokenUrl = "https://github.com/login/oauth/access_token"
    def apiUrl = "https://api.github.com/user"
    def emailsUrl = "https://api.github.com/user/emails"

    // Validate configuration
    if (clientId == "your_github_client_id" || clientSecret == "your_github_client_secret") {
        success = false
        message = "GitHub OAuth is not configured. Please set GITHUB_CLIENT_ID and GITHUB_CLIENT_SECRET environment variables."
        errorCode = "OAUTH_NOT_CONFIGURED"
        return
    }

    // Step 1: Exchange authorization code for access token
    def httpClient = HttpClient.newBuilder()
        .version(HttpClient.Version.HTTP_2)
        .build()

    def tokenRequestBody = new JsonBuilder([
        client_id: clientId,
        client_secret: clientSecret,
        code: code
    ]).toString()

    def tokenRequest = HttpRequest.newBuilder()
        .uri(URI.create(tokenUrl))
        .header("Content-Type", "application/json")
        .header("Accept", "application/json")
        .POST(HttpRequest.BodyPublishers.ofString(tokenRequestBody))
        .build()

    def tokenResponse = httpClient.send(tokenRequest, HttpResponse.BodyHandlers.ofString())

    if (tokenResponse.statusCode() != 200) {
        ec.logger.error("GitHub token exchange failed: ${tokenResponse.body()}")
        success = false
        message = "Failed to exchange authorization code. Please try again."
        errorCode = "TOKEN_EXCHANGE_FAILED"
        return
    }

    def tokenData = new JsonSlurper().parseText(tokenResponse.body())

    if (tokenData.error) {
        ec.logger.error("GitHub OAuth error: ${tokenData.error_description ?: tokenData.error}")
        success = false
        message = tokenData.error_description ?: "GitHub authorization failed."
        errorCode = "GITHUB_AUTH_ERROR"
        return
    }

    def githubAccessToken = tokenData.access_token
    if (!githubAccessToken) {
        success = false
        message = "No access token received from GitHub."
        errorCode = "NO_ACCESS_TOKEN"
        return
    }

    // Step 2: Fetch user profile from GitHub API
    def userRequest = HttpRequest.newBuilder()
        .uri(URI.create(apiUrl))
        .header("Authorization", "Bearer ${githubAccessToken}")
        .header("Accept", "application/vnd.github+json")
        .header("X-GitHub-Api-Version", "2022-11-28")
        .GET()
        .build()

    def userResponse = httpClient.send(userRequest, HttpResponse.BodyHandlers.ofString())

    if (userResponse.statusCode() != 200) {
        ec.logger.error("GitHub user fetch failed: ${userResponse.body()}")
        success = false
        message = "Failed to fetch user profile from GitHub."
        errorCode = "USER_FETCH_FAILED"
        return
    }

    def githubUser = new JsonSlurper().parseText(userResponse.body())
    def githubUserId = githubUser.id?.toString()
    def githubUsername = githubUser.login
    def githubEmail = githubUser.email
    def githubAvatarUrl = githubUser.avatar_url
    def githubName = githubUser.name ?: githubUsername

    // Step 3: If email is not public, fetch from emails endpoint
    if (!githubEmail) {
        def emailsRequest = HttpRequest.newBuilder()
            .uri(URI.create(emailsUrl))
            .header("Authorization", "Bearer ${githubAccessToken}")
            .header("Accept", "application/vnd.github+json")
            .header("X-GitHub-Api-Version", "2022-11-28")
            .GET()
            .build()

        def emailsResponse = httpClient.send(emailsRequest, HttpResponse.BodyHandlers.ofString())

        if (emailsResponse.statusCode() == 200) {
            def emails = new JsonSlurper().parseText(emailsResponse.body())
            // Find primary email or first verified email
            def primaryEmail = emails.find { it.primary && it.verified }
            if (!primaryEmail) {
                primaryEmail = emails.find { it.verified }
            }
            if (primaryEmail) {
                githubEmail = primaryEmail.email
            }
        }
    }

    if (!githubEmail) {
        success = false
        message = "Could not retrieve email from GitHub. Please ensure your email is verified on GitHub."
        errorCode = "NO_EMAIL"
        return
    }

    ec.logger.info("GitHub user fetched: ${githubUsername} (${githubEmail})")

    // Step 4: Call the user creation/linking service
    def createResult = ec.service.sync().name("novel.anime.NovelAnimeAuthServices.createOrLink#GitHubUser")
        .parameters([
            githubUserId: githubUserId,
            email: githubEmail,
            username: githubName,
            avatarUrl: githubAvatarUrl,
            githubAccessToken: githubAccessToken,
            profileData: userResponse.body()
        ])
        .disableAuthz()
        .call()

    if (!createResult.success) {
        success = false
        message = createResult.message
        errorCode = createResult.errorCode
        return
    }

    // Return the results
    success = true
    accessToken = createResult.accessToken
    refreshToken = createResult.refreshToken
    expiresIn = createResult.expiresIn
    user = createResult.user
    isNewUser = createResult.isNewUser
    message = createResult.message

} catch (Exception e) {
    ec.logger.error("GitHub OAuth login failed", e)
    success = false
    message = "GitHub login failed: " + e.message
    errorCode = "GITHUB_LOGIN_ERROR"
}

import java.net.URLEncoder

// Handle error from GitHub (Requirement 2.1.3)
if (error) {
    success = false
    message = error_description ?: "GitHub authorization was denied or failed."
    errorCode = "GITHUB_AUTH_DENIED"
    redirectUrl = "novelanime://auth/error?message=${URLEncoder.encode(message, 'UTF-8')}"
    return
}

if (!code) {
    success = false
    message = "No authorization code received from GitHub."
    errorCode = "NO_AUTH_CODE"
    redirectUrl = "novelanime://auth/error?message=${URLEncoder.encode(message, 'UTF-8')}"
    return
}

// Call the main login service
def loginResult = ec.service.sync().name("novel.anime.NovelAnimeAuthServices.login#WithGitHub")
    .parameters([code: code, state: state])
    .disableAuthz()
    .call()

success = loginResult.success
accessToken = loginResult.accessToken
refreshToken = loginResult.refreshToken
expiresIn = loginResult.expiresIn
user = loginResult.user
isNewUser = loginResult.isNewUser
message = loginResult.message
errorCode = loginResult.errorCode

// Generate redirect URL for desktop app
if (success) {
    redirectUrl = "novelanime://auth/success?token=${accessToken}&amp;refresh=${refreshToken}"
} else {
    redirectUrl = "novelanime://auth/error?message=${URLEncoder.encode(message ?: 'Login failed', 'UTF-8')}"
}

import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.time.Instant
import java.nio.charset.StandardCharsets
import groovy.json.JsonBuilder

try {
    def now = ec.user.nowTimestamp
    isNewUser = false
    ec.artifactExecution.disableAuthz()

    // Step 1: Check if OAuth account already exists (Requirement 5.1)
    def existingOAuth = ec.entity.find("novel.anime.user.UserOAuthAccount")
        .condition("provider", "github")
        .condition("providerUserId", githubUserId)
        .one()

    def userAccount = null
    def novelAnimeUser = null

    if (existingOAuth) {
        // User has logged in with GitHub before - get existing UserAccount
        userAccount = ec.entity.find("moqui.security.UserAccount")
            .condition("userId", existingOAuth.userId)
            .one()

        if (!userAccount) {
            // Orphaned OAuth account - clean up and create new user
            existingOAuth.delete()
            existingOAuth = null
        } else {
            // Get NovelAnimeUser
            novelAnimeUser = ec.entity.find("novel.anime.user.NovelAnimeUser")
                .condition("userId", existingOAuth.userId)
                .one()

            // Update OAuth account with latest token
            existingOAuth.accessToken = githubAccessToken
            existingOAuth.profileData = profileData
            existingOAuth.lastUsedDate = now
            existingOAuth.update()

            // Update NovelAnimeUser's last login and avatar
            if (novelAnimeUser) {
                novelAnimeUser.lastLoginDate = now
                if (avatarUrl && !novelAnimeUser.avatarUrl) {
                    novelAnimeUser.avatarUrl = avatarUrl
                }
                novelAnimeUser.update()
            }

            userId = userAccount.userId
            ec.logger.info("Existing GitHub user logged in: ${email}")
        }
    }

    if (!userAccount) {
        // Step 2: Check if UserAccount exists with same email (Requirement 5.2)
        userAccount = ec.entity.find("moqui.security.UserAccount")
            .condition("emailAddress", email.toLowerCase().trim())
            .one()

        if (userAccount) {
            // Link GitHub account to existing UserAccount
            userId = userAccount.userId

            // Get or create NovelAnimeUser
            novelAnimeUser = ec.entity.find("novel.anime.user.NovelAnimeUser")
                .condition("userId", userId)
                .one()

            if (!novelAnimeUser) {
                // Create NovelAnimeUser with default credits
                novelAnimeUser = ec.entity.makeValue("novel.anime.user.NovelAnimeUser").setAll([
                    userId: userId,
                    avatarUrl: avatarUrl,
                    credits: 500,
                    status: 'active',
                    createdDate: now,
                    lastLoginDate: now
                ])
                novelAnimeUser.create()

                // Record initial credits transaction
                ec.entity.makeValue("novel.anime.user.CreditTransaction").setAll([
                    transactionId: UUID.randomUUID().toString(),
                    userId: userId,
                    amount: 500,
                    type: 'initial',
                    operationType: 'github_link',
                    description: 'Initial credits on GitHub account link',
                    balanceAfter: 500,
                    timestamp: now
                ]).create()
            } else {
                // Update existing NovelAnimeUser
                novelAnimeUser.lastLoginDate = now
                if (avatarUrl && !novelAnimeUser.avatarUrl) {
                    novelAnimeUser.avatarUrl = avatarUrl
                }
                novelAnimeUser.update()
            }

            // Create OAuth account link
            ec.entity.makeValue("novel.anime.user.UserOAuthAccount").setAll([
                oauthAccountId: UUID.randomUUID().toString(),
                userId: userId,
                provider: "github",
                providerUserId: githubUserId,
                accessToken: githubAccessToken,
                profileData: profileData,
                createdDate: now,
                lastUsedDate: now
            ]).create()

            ec.logger.info("GitHub account linked to existing user: ${email}")

        } else {
            // Step 3: Create new UserAccount first, then NovelAnimeUser (Requirement 5.2)
            isNewUser = true
            userId = UUID.randomUUID().toString()
            def displayName = username ?: email.split('@')[0]

            // Create UserAccount (Moqui's built-in user entity)
            userAccount = ec.entity.makeValue("moqui.security.UserAccount").setAll([
                userId: userId,
                username: "github_${githubUserId}",
                emailAddress: email.toLowerCase().trim(),
                userFullName: displayName,
                disabled: 'N',
                requirePasswordChange: 'N'
            ])
            userAccount.create()

            // Create NovelAnimeUser (business extension)
            novelAnimeUser = ec.entity.makeValue("novel.anime.user.NovelAnimeUser").setAll([
                userId: userId,
                avatarUrl: avatarUrl,
                credits: 500,
                status: 'active',
                createdDate: now,
                lastLoginDate: now
            ])
            novelAnimeUser.create()

            // Record initial credits transaction
            ec.entity.makeValue("novel.anime.user.CreditTransaction").setAll([
                transactionId: UUID.randomUUID().toString(),
                userId: userId,
                amount: 500,
                type: 'initial',
                operationType: 'github_registration',
                description: 'Initial credits on GitHub registration',
                balanceAfter: 500,
                timestamp: now
            ]).create()

            // Create OAuth account link
            ec.entity.makeValue("novel.anime.user.UserOAuthAccount").setAll([
                oauthAccountId: UUID.randomUUID().toString(),
                userId: userId,
                provider: "github",
                providerUserId: githubUserId,
                accessToken: githubAccessToken,
                profileData: profileData,
                createdDate: now,
                lastUsedDate: now
            ]).create()

            ec.logger.info("New GitHub user created: ${email} with 500 initial credits")
        }
    }

    ec.artifactExecution.enableAuthz()

    // Step 4: Generate JWT tokens
    def jwtSecret = "MoquiJWTSecretKey123456789012345678901234567890"
    def accessExpiryTime = Instant.now().plusSeconds(3600) // 1 hour
    def refreshExpiryTime = Instant.now().plusSeconds(604800) // 7 days

    // Create JWT Header
    def header = new JsonBuilder([
        alg: "HS256",
        typ: "JWT"
    ]).toString()

    // Create Access Token payload
    def accessPayload = new JsonBuilder([
        sub: userId,
        email: userAccount.emailAddress,
        provider: "github",
        iat: Instant.now().epochSecond,
        exp: accessExpiryTime.epochSecond,
        type: "access"
    ]).toString()

    // Create Refresh Token payload
    def refreshPayload = new JsonBuilder([
        sub: userId,
        iat: Instant.now().epochSecond,
        exp: refreshExpiryTime.epochSecond,
        type: "refresh"
    ]).toString()

    // Base64 encode
    def encodedHeader = Base64.urlEncoder.withoutPadding().encodeToString(header.getBytes(StandardCharsets.UTF_8))
    def encodedAccessPayload = Base64.urlEncoder.withoutPadding().encodeToString(accessPayload.getBytes(StandardCharsets.UTF_8))
    def encodedRefreshPayload = Base64.urlEncoder.withoutPadding().encodeToString(refreshPayload.getBytes(StandardCharsets.UTF_8))

    // Create signatures
    def mac = Mac.getInstance("HmacSHA256")
    def secretKey = new SecretKeySpec(jwtSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256")
    mac.init(secretKey)

    def accessTokenData = encodedHeader + "." + encodedAccessPayload
    def accessSignature = Base64.urlEncoder.withoutPadding().encodeToString(mac.doFinal(accessTokenData.getBytes(StandardCharsets.UTF_8)))

    mac.reset()
    mac.init(secretKey)
    def refreshTokenData = encodedHeader + "." + encodedRefreshPayload
    def refreshSignature = Base64.urlEncoder.withoutPadding().encodeToString(mac.doFinal(refreshTokenData.getBytes(StandardCharsets.UTF_8)))

    accessToken = accessTokenData + "." + accessSignature
    refreshToken = refreshTokenData + "." + refreshSignature
    expiresIn = 3600L

    // Build unified user response (Requirement 5.3 - same as regular login)
    user = [
        userId: userId,
        username: userAccount.username,
        email: userAccount.emailAddress,
        fullName: userAccount.userFullName,
        credits: novelAnimeUser?.credits ?: 500,
        avatarUrl: novelAnimeUser?.avatarUrl,
        status: novelAnimeUser?.status ?: 'active',
        createdDate: novelAnimeUser?.createdDate?.toString(),
        lastLoginDate: novelAnimeUser?.lastLoginDate?.toString()
    ]

    success = true
    message = isNewUser ? "Welcome to Novel Anime! Your account has been created with 500 credits." : "GitHub login successful."

} catch (Exception e) {
    ec.artifactExecution.enableAuthz()
    ec.logger.error("GitHub user creation/linking failed", e)
    success = false
    message = "Failed to create or link GitHub account: " + e.message
    errorCode = "USER_CREATION_ERROR"
}

